mapper.select:


SELECT opt.TARGET_ID as targetId , opt.TARGET_NAME targetName,opt.TARGET_TYPE targetType,mst.VALUATION, TO_CHAR(mst.VAL_DATE, 'yyyy-MM-dd') as valDate ,mst.FINPROD_ID2,TO_CHAR(mst.PUBLISH_DATE, 'yyyy-MM-dd') as publishDate
FROM MST_VAL_OP mst LEFT JOIN FIN_RATE_INFO fin  ON fin.FINPROD_ID=mst.FINPROD_ID2
AND		fin.BENCHMARK_TYPE = #{BENCHMARK_TYPE2}
LEFT JOIN OPT_TARGET_INFO opt ON opt.TARGET_ID = fin.BENCHMARK_ID
where mst.FINPROD_ID2 = #{finprodId2,jdbcType=VARCHAR} and mst.VAL_DATE = TO_DATE(#{valDate}, 'yyyy-MM-dd')

    and opt.TARGET_ID= #{targetId}

SELECT opt.TARGET_ID as targetId ,opt.TARGET_NAME targetName,opt.TARGET_TYPE targetType, mst.VALUATION, TO_CHAR(mst.VAL_DATE, 'yyyy-MM-dd') as valDate ,mst.FINPROD_ID2,TO_CHAR(mst.PUBLISH_DATE, 'yyyy-MM-dd') as publishDate
FROM MST_VAL_OP mst LEFT JOIN FIN_RATE_INFO fin  ON fin.FINPROD_ID=mst.FINPROD_ID2
AND		fin.BENCHMARK_TYPE = #{BENCHMARK_TYPE2}
LEFT JOIN OPT_TARGET_INFO opt ON opt.TARGET_ID = fin.BENCHMARK_ID


        fin.BENCHMARK_ID= #{targetId}


        AND fin.FINPROD_ID = #{finprodId}


        AND opt.TARGET_TYPE = #{targetType}


        AND mst.VAL_DATE = to_date(#{valDate},'yyyy-mm-dd')



GROUP BY opt.TARGET_ID , opt.TARGET_NAME,opt.TARGET_TYPE,mst.VALUATION, mst.VAL_DATE,mst.FINPROD_ID2,mst.PUBLISH_DATE

select TO_CHAR(ftp.VDATE, 'yyyy-MM-dd') as vdate ,TO_CHAR(ftp.MDATE, 'yyyy-MM-dd') as mdate
FROM FIN_TRADE_PRODUCT ftp
where ftp.FINPROD_ID = #{finprodId2}
and ftp.BRANCH = #{branch}
